// Test bench for sdram_video_core
//
//  * W25Q64 SPI flash model loaded with MEM.TXT (random 1 MByte image at
//    0x600000, generated by tools/mkimage.py)
//  * burst capable SDRAM model (sim/sdram_model_burst.v)
//
// Checks:
//  1. After the flash copy, the first COPY_WORDS words of the SDRAM model
//     equal the image.
//  2. FRAMES complete 640x480 HDMI frames: every pixel is compared with the
//     expected (line doubled, pixel doubled, RGB565 -> RGB888) image pixel.
//     The first frame is also written to frame.ppm.
//  3. SDRAM model timing/protocol errors, CDC overrun / late fetch flags.
//
// To keep the simulation short only COPY_WORDS words are copied from flash;
// the rest of the frame buffer is back-door loaded into the SDRAM model.

`timescale 1ns / 1ps

module tb_sdram_video;

   parameter        COPY_WORDS     = 4096;
   parameter real   SDRAM_PERIOD   = 19.841;  // 50.4 MHz
   parameter        SDRAM_FREQ_KHZ = 50400;
   parameter real   PIXEL_PERIOD   = 39.683;  // 25.2 MHz
   parameter        FRAMES         = 1;
   parameter        FLASH_START    = 24'h600000;
   parameter        RD_EXTRA       = 0;

   localparam FRAME_WORDS = 320 * 240 / 2;
   localparam IMG_WORDS = 262144;

   // ---------------- clocks / reset ----------------
   reg clk_pixel = 0;
   reg clk_sdram = 0;
   reg rst_n = 0;

   initial
     begin
        #(3.1);
        forever #(PIXEL_PERIOD / 2) clk_pixel = ~clk_pixel;
     end

   initial
     begin
        #(1.7);
        forever #(SDRAM_PERIOD / 2) clk_sdram = ~clk_sdram;
     end

   initial
     begin
        #(100);
        rst_n = 1;
     end

   // ---------------- DUT ----------------
   wire        mspi_cs, mspi_clk, mspi_di, mspi_do;
   wire [31:0] sdram_dq;
   wire [10:0] sdram_addr;
   wire [1:0]  sdram_ba;
   wire        sdram_cs_n, sdram_wen_n, sdram_ras_n, sdram_cas_n, sdram_cke;
   wire [3:0]  sdram_dqm;
   wire [9:0]  xpos, ypos;
   wire [23:0] rgb_data;
   wire        copy_done;

   sdram_video_core #(.FLASH_START(FLASH_START),
                      .COPY_WORDS(COPY_WORDS),
                      .SDRAM_FREQ_KHZ(SDRAM_FREQ_KHZ),
                      .SDRAM_RD_EXTRA(RD_EXTRA))
   dut(.clk_pixel(clk_pixel),
       .clk_sdram(clk_sdram),
       .rst_n(rst_n),
       .mspi_cs(mspi_cs),
       .mspi_clk(mspi_clk),
       .mspi_di(mspi_di),
       .mspi_do(mspi_do),
       .sdram_dq(sdram_dq),
       .sdram_addr(sdram_addr),
       .sdram_ba(sdram_ba),
       .sdram_cs_n(sdram_cs_n),
       .sdram_wen_n(sdram_wen_n),
       .sdram_ras_n(sdram_ras_n),
       .sdram_cas_n(sdram_cas_n),
       .sdram_cke(sdram_cke),
       .sdram_dqm(sdram_dqm),
       .tmds_r(),
       .tmds_g(),
       .tmds_b(),
       .xpos(xpos),
       .ypos(ypos),
       .rgb_data(rgb_data),
       .copy_done(copy_done));

   W25Q64JVxxIM spi_flash(.CSn(mspi_cs),
                          .CLK(mspi_clk),
                          .DIO(mspi_di),
                          .DO(mspi_do),
                          .RESETn(rst_n));

   // The SDRAM CLK pin is driven by the controller clock. A continuous
   // assign (no delay) makes the model sample the pins before the
   // controller's registers update on the same edge, like the real chip.
   wire sdram_clk_chip = clk_sdram;

   // tAC (CL2) / tOH include ~1.5ns board / input buffer delay
   sdram_model_burst #(.TAC(7.5), .TOH(4.0))
   sdram(.clk(sdram_clk_chip),
         .cke(sdram_cke),
         .cs_n(sdram_cs_n),
         .ras_n(sdram_ras_n),
         .cas_n(sdram_cas_n),
         .we_n(sdram_wen_n),
         .ba(sdram_ba),
         .a(sdram_addr),
         .dqm(sdram_dqm),
         .dq(sdram_dq));

   // ---------------- reference image ----------------
   reg [31:0] img [0:IMG_WORDS-1];
   integer    i, errors;

   initial
     begin
        errors = 0;
        $readmemh("image_words.hex", img);
        // back-door load the part of the frame buffer not copied from flash
        for (i = COPY_WORDS; i < FRAME_WORDS; i = i + 1)
          sdram.mem[i] = img[i];
        $display("TB: COPY_WORDS=%0d SDRAM %0d kHz (period %0.3f ns)",
                 COPY_WORDS, SDRAM_FREQ_KHZ, SDRAM_PERIOD);
     end

   function [23:0] expand;
      input [15:0] p;
      expand = { p[15:11], p[15:13], p[10:5], p[10:9], p[4:0], p[4:2] };
   endfunction

   // ---------------- progress ----------------
   always @(posedge dut.sdram_ready)
     $display("%t TB: SDRAM controller ready", $realtime);

   always @(posedge clk_pixel)
     if (dut.flash_strobe && (dut.flash_word_addr % 1024) == 0)
       $display("%t TB: flash word %0d", $realtime, dut.flash_word_addr);

   // ---------------- check 1: copied data ----------------
   integer copy_err;
   initial
     begin
        copy_err = 0;
        wait (copy_done === 1'b1);
        $display("%t TB: flash copy done", $realtime);
        #(SDRAM_PERIOD * 20);
        for (i = 0; i < COPY_WORDS; i = i + 1)
          if (sdram.mem[i] !== img[i])
            begin
               if (copy_err < 10)
                 $display("TB ERROR: SDRAM word %0d = %08x, expected %08x", i, sdram.mem[i], img[i]);
               copy_err = copy_err + 1;
            end
        $display("TB: copy check: %0d of %0d words wrong", copy_err, COPY_WORDS);
        errors = errors + copy_err;
     end

   // ---------------- check 2: video frames ----------------
   reg [9:0] x_d1, x_d2, y_d1, y_d2;
   always @(posedge clk_pixel)
     begin
        x_d1 <= xpos; x_d2 <= x_d1;
        y_d1 <= ypos; y_d2 <= y_d1;
     end

   integer frame_err, frame_no, fd;
   reg [31:0] w;
   reg [15:0] p;
   reg [23:0] exp_rgb;
   reg        capture;

   initial
     begin
        capture = 0;
        frame_err = 0;
        wait (copy_done === 1'b1);
        // the first complete frame after the copy (line 0 is fetched at ypos 524)
        @(posedge clk_pixel);
        wait (ypos == 10'd523);
        for (frame_no = 0; frame_no < FRAMES; frame_no = frame_no + 1)
          begin
             wait (y_d2 == 10'd0 && x_d2 == 10'd0);
             $display("%t TB: checking frame %0d", $realtime, frame_no);
             if (frame_no == 0)
               begin
                  fd = $fopen("frame.ppm", "w");
                  $fwrite(fd, "P3\n640 480\n255\n");
               end
             capture = 1;
             wait (y_d2 == 10'd480);
             capture = 0;
             if (frame_no == 0)
               $fclose(fd);
             $display("%t TB: frame %0d done, %0d pixel errors so far", $realtime, frame_no, frame_err);
          end
        errors = errors + frame_err;
        finish_test;
     end

   always @(negedge clk_pixel)
     if (capture && x_d2 < 640 && y_d2 < 480)
       begin
          w = img[(y_d2 >> 1) * 160 + (x_d2 >> 2)];
          p = x_d2[1] ? w[15:0] : w[31:16];
          exp_rgb = expand(p);
          if (rgb_data !== exp_rgb)
            begin
               if (frame_err < 20)
                 $display("TB ERROR: pixel (%0d,%0d) = %06x, expected %06x", x_d2, y_d2, rgb_data, exp_rgb);
               frame_err = frame_err + 1;
            end
          if (frame_no == 0)
            $fwrite(fd, "%0d %0d %0d\n", rgb_data[23:16], rgb_data[15:8], rgb_data[7:0]);
       end

   // ---------------- summary ----------------
   task finish_test;
      begin
         sdram.report;
         if (dut.copy_overrun) begin $display("TB ERROR: flash->SDRAM write overrun"); errors = errors + 1; end
         if (dut.fetch_late)   begin $display("TB ERROR: line fetch request while busy"); errors = errors + 1; end
         errors = errors + sdram.errors;
         if (errors == 0)
           $display("TB: PASS");
         else
           $display("TB: FAIL (%0d errors)", errors);
         $finish;
      end
   endtask

   initial
     begin
        // watchdog: flash copy + 2 frames + margin
        #(1.0e6 + COPY_WORDS * 64.0 * PIXEL_PERIOD * 1.2 + (FRAMES + 2) * 420000.0 * PIXEL_PERIOD);
        $display("TB ERROR: timeout");
        sdram.report;
        $display("TB: FAIL (timeout)");
        $finish;
     end

endmodule // tb_sdram_video
